 [W("desk", "/desk/", N, "робочий стіл", "I work at my desk.", "Я працюю за своїм столом."),
  W("lunch break", "/ˈlʌntʃ breɪk/", N, "обідня перерва", "My lunch break is at one.", "Моя обідня перерва о першій."),
  W("coffee break", "/ˈkɒfi breɪk/", N, "перерва на каву", "We have a coffee break at eleven.", "У нас перерва на каву об одинадцятій."),
  W("report", "/rɪˈpɔːt/", N, "звіт", "I write a report on Fridays.", "Я пишу звіт по п'ятницях."),
  W("project", "/ˈprɒdʒekt/", N, "проєкт", "We have a new project.", "У нас новий проєкт.")],
