  liu("My lunch break is at one.", "Прослухайте. Коли обідня перерва?", ["О першій", "О дванадцятій", "О другій"], "At one."),
  liu("We have a coffee break at eleven.", "Прослухайте. Коли перерва на каву?", ["О одинадцятій", "О десятій", "О дванадцятій"], "At eleven."),
  liu("I write a report on Fridays.", "Прослухайте. Коли людина пише звіт?", ["По п'ятницях", "По понеділках", "По середах"], "On Fridays."),
  fb("I work at my ___.", ["desk", "report", "project"], "Desk."),
