  W("send an email", "/ˌsend ən ˈiːmeɪl/", "phrase", "надіслати лист", "I send ten emails a day.", "Я надсилаю десять листів на день."),
  W("answer the phone", "/ˌɑːnsə ðə ˈfəʊn/", "phrase", "відповісти на дзвінок", "I answer the phone all day.", "Я відповідаю на дзвінки цілий день."),
  W("make a call", "/ˌmeɪk ə ˈkɔːl/", "phrase", "зателефонувати", "I make three calls a day.", "Я роблю три дзвінки на день."),
