  mt([("customer", "покупець"), ("client", "клієнт"), ("task", "завдання"), ("deadline", "крайній термін"), ("schedule", "розклад")], "Слова про клієнтів і терміни."),
  liu("The customer is waiting.", "Прослухайте. Що робить покупець?", ["Чекає", "Платить", "Йде"], "Waiting."),
  liu("I have an appointment at four.", "Прослухайте. Коли запис?", ["О четвертій", "О третій", "О п'ятій"], "At four."),
  liu("The deadline is Friday.", "Прослухайте. Коли крайній термін?", ["У п'ятницю", "У четвер", "У середу"], "Friday."),
