  fb("I have a ___ at three. (клієнт)", ["client", "customer is", "appointment's"], "Client."),
  fb("My ___ is busy.", ["schedule", "deadline", "report"], "Schedule."),
  mc("Хто купує товар у магазині?", ["customer", "client", "colleague"], "Customer."),
